commands:
cd <WORKSPACE>/smb-infrastructure-dashboard
J=/tmp/dh_cookies.txt
# Check port data via a quick sqlite query if db accessible
DB=$(find . -name "*.sqlite" -not -path "*/node_modules/*" 2>/dev/null | head -1)
echo "DB=$DB"
if [ -n "$DB" ]; then
  bunx --bun node -e "
  const {Database}=require('bun:sqlite');
  const db=new Database('$DB',{readonly:true});
  console.log('ports total:', db.query('select count(*) c from asset_ports').get());
  console.log('unverified/needs_review:', db.query(\"select count(*) c from asset_ports where verified_at is null or review_state='needs_review'\").get());
  " 2>&1 || echo "node sqlite failed"
fi

cd <WORKSPACE>/smb-infrastructure-dashboard
bunx --bun node -e "
const {Database}=require('bun:sqlite');
const db=new Database('./data/smb-infrastructure-dashboard.db',{readonly:true});
console.log('ports total:', JSON.stringify(db.query('select count(*) c from asset_ports').get()));
console.log('unverified/needs_review:', JSON.stringify(db.query(\"select count(*) c from asset_ports where verified_at is null or review_state='needs_review'\").get()));
console.log('review_state distr:', JSON.stringify(db.query('select review_state, count(*) c from asset_ports group by review_state').all()));
" 2>&1

cd <WORKSPACE>/smb-infrastructure-dashboard
bunx --bun node -e "
const {Database}=require('bun:sqlite');
const db=new Database('./data/smb-infrastructure-dashboard.db',{readonly:true});
const cols=db.query('PRAGMA table_info(asset_ports)').all().map(c=>c.name+':'+c.type+(c.notnull?' NN':'')+(c.dflt_value?' D='+c.dflt_value:''));
console.log(cols.join('\n'));
"

cd <WORKSPACE>/smb-infrastructure-dashboard
J=/tmp/dh_cookies.txt
bunx --bun node -e "
const {Database}=require('bun:sqlite');
const db=new Database('./data/smb-infrastructure-dashboard.db');
const now=1751580000;
db.run(\"insert into asset_ports (asset_id,port_number,protocol,exposure_level,review_state,source,created_at,updated_at,verified_at) values (1,3389,'tcp','unknown','needs_review','documented',?,?,NULL)\",[now,now]);
console.log('inserted needs_review port for asset 1');
"
echo "=== unverifiedPorts after inject ==="
curl -s -b $J "http://localhost:3461/api/v1/infrastructure/documentation-health/assets?signal=unverifiedPorts&limit=3" | bunx --bun node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{const j=JSON.parse(s);console.log('total='+j.total+' names='+j.data.map(a=>a.name).join(','))})"
# cleanup
bunx --bun node -e "
const {Database}=require('bun:sqlite');
const db=new Database('./data/smb-infrastructure-dashboard.db');
db.run(\"delete from asset_ports where port_number=3389 and asset_id=1 and review_state='needs_review'\");
console.log('cleaned up test port');
"
echo "=== unverifiedPorts after cleanup ==="
curl -s -b $J "http://localhost:3461/api/v1/infrastructure/documentation-health?" | bunx --bun node -e "let s='';process.stdin.on('data',d=>s+=d).on('end',()=>{console.log('unverifiedPorts='+JSON.parse(s).data.signals.unverifiedPorts)})"
